import {authFetch} from './auth.mjs';
import {sharedSnapshot} from './shared-trip.mjs';
async function api(path,options){const response=await authFetch(path,{...options,headers:{'Content-Type':'application/json'},cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||'No s’ha pogut sincronitzar.');return data;}
export async function shareTrip(trip){const snapshot=sharedSnapshot(trip),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(snapshot))))).map(x=>x.toString(16).padStart(2,'0')).join('');if(trip.shared?.digest===digest)return trip.shared;let data;try{data=await api('/api/admin/trips/'+encodeURIComponent(trip.id),{method:'PUT',body:JSON.stringify({trip:snapshot,expectedRevision:trip.shared?.revision||0})})}catch(e){trip.sharedError=e.message;throw e}trip.shared={revision:data.revision,updatedAt:data.updatedAt,digest};delete trip.sharedError;return data;}
export async function sharedFeedback(trip){return api('/api/admin/trips/'+encodeURIComponent(trip.id));}
export function sharedPanel(trip,esc){const missing=trip.people.filter(p=>!p.email).length;return `<section class="panel"><div class="section-head"><div><h3>Accés dels esportistes</h3><p>${trip.shared?'Compartit · última sincronització '+esc(new Date(trip.shared.updatedAt).toLocaleString('ca-ES')):'Encara no s’ha compartit aquest viatge.'}</p></div><button class="button" data-action="share-trip">${trip.shared?'Actualitzar viatge compartit':'Compartir itineraris'}</button></div>${trip.sharedError?`<div class="notice">Canvis pendents de compartir: ${esc(trip.sharedError)}</div>`:''}<p>${missing} participants sense email personal. Cada persona només podrà consultar les seves dades.</p><div class="actions"><button class="button secondary" data-action="shared-feedback">Veure confirmacions</button><a class="button secondary" href="/me" target="_blank" rel="noopener">Portal dels esportistes ↗</a></div><p class="small muted">Cal autoritzar els emails personals a l’accés privat del lloc. Afegir un email a la fitxa no envia invitacions. Els documents originals continuen al teu ordinador.</p></section>`;}
